@page "/dashboard"
@inject Services.InventoryAlertService AlertService
@inject Services.WarehouseState WarehouseState
@implements IAsyncDisposable
@rendermode InteractiveServer

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>
<h4 class="text-muted mb-4">@WarehouseState.SelectedWarehouseName</h4>

<div class="row">
    <div class="col-md-4">
        <div class="card border-danger">
            <div class="card-body text-center">
                <h5 class="card-title text-danger">Low Stock Alerts</h5>
                <p class="display-4">@AlertService.LastLowStockCount</p>
                <p class="text-muted small">
                    Items below minimum levels<br />
                    Refreshes every 10 seconds
                </p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Active Warehouse</h5>
                <p class="display-6">@WarehouseState.SelectedWarehouseId</p>
                <p class="text-muted small">@WarehouseState.SelectedWarehouseName</p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Polling Status</h5>
                <p class="display-6">@(_isPolling ? "Active" : "Stopped")</p>
                <p class="text-muted small">Last check: @_lastCheck.ToString("HH:mm:ss")</p>
            </div>
        </div>
    </div>
</div>

@code {
    private CancellationTokenSource _cts = new();
    private bool _isPolling;
    private DateTime _lastCheck = DateTime.Now;
    private Action? _alertHandler;
    private Action? _warehouseHandler;

    protected override void OnInitialized()
    {
        _alertHandler = () => InvokeAsync(StateHasChanged);
        _warehouseHandler = () => InvokeAsync(OnWarehouseChanged);

        AlertService.OnAlertCountChanged += _alertHandler;
        WarehouseState.OnChange += _warehouseHandler;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _isPolling = true;
            _ = PollForAlertsAsync(_cts.Token);
            // Initial fetch
            await AlertService.RefreshAlertCountAsync(WarehouseState.SelectedWarehouseId);
        }
    }

    private async Task OnWarehouseChanged()
    {
        // Immediately refresh alerts for the newly selected warehouse
        await AlertService.RefreshAlertCountAsync(WarehouseState.SelectedWarehouseId);
        StateHasChanged();
    }

    private async Task PollForAlertsAsync(CancellationToken ct)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        try
        {
            while (await timer.WaitForNextTickAsync(ct))
            {
                await AlertService.RefreshAlertCountAsync(WarehouseState.SelectedWarehouseId);
                _lastCheck = DateTime.Now;
                await InvokeAsync(StateHasChanged);
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on dispose
        }
    }

    public async ValueTask DisposeAsync()
    {
        _isPolling = false;
        await _cts.CancelAsync();
        _cts.Dispose();

        AlertService.OnAlertCountChanged -= _alertHandler;
        WarehouseState.OnChange -= _warehouseHandler;
    }
}

